// Structural selectors verified against the live profile header, Albums and Showcase.
export function profileFixture(handle = "batu", account = "FixturePlayer") {
  return `<!doctype html><html><head><meta charset="utf-8"><title>${handle} · Profile</title><style>
  *{box-sizing:border-box}body{margin:0;background:#0b081d;color:#f4f1ff;font:14px/1.5 system-ui}.rail{padding:16px 32px}.rail a{color:#c9b4e4}.pf{max-width:1100px;margin:auto;padding:28px 32px 40px;display:flex;flex-direction:column;gap:44px}.pf-banner{padding:30px;border-radius:20px;background:radial-gradient(60% 90% at 12% 0,#6e46dc59,transparent 70%),linear-gradient(165deg,#1b1545,#0b0a24 70%);border:1px solid #cab4ff26}.pf-id{display:flex;gap:24px;align-items:center}.avatar{width:90px;height:90px;border-radius:50%;background:#4c3d69;border:2px solid #dec17f;display:grid;place-items:center;font:36px Georgia}.pf-name{font:700 40px Georgia;color:#fff3c4;margin:0}.sub{color:#b5a6ca}.pf-stats{margin-top:24px;display:flex;gap:8px}.pf-stats span{padding:12px 22px;background:#0e0a22;border-radius:14px}.sec{display:grid;gap:14px}.sec h2{font:700 18.4px Georgia;color:#fff3c4;margin:0;text-transform:uppercase}.tiles{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px}.tile{padding:28px;border-radius:22px;background:radial-gradient(90% 60% at 50% 0,#6e46dc4d,transparent 72%),linear-gradient(170deg,#1b1545,#0c0a26 75%);border:1px solid #cab4ff26}.tile div{height:70px;background:#3a2c5b;border-radius:9px;margin-bottom:16px}@media(max-width:650px){.pf{padding:20px 16px;gap:36px}.pf-banner{padding:20px}.pf-name{font-size:28px}.avatar{width:55px;height:55px}.pf-id{gap:16px}.pf-stats span{padding:8px}.tiles{grid-template-columns:1fr}}
  </style></head><body><aside class="rail"><a href="/u/${account}">${account} · Your profile</a></aside><main id="main"><div class="screen pf pf2"><header class="pf-banner"><div class="pf-id"><div class="avatar">${handle.slice(0, 1).toUpperCase()}</div><div class="pf-id-text"><h1 class="pf-name">${handle}</h1><p class="sub">✦ Star · Collecting since November 2026</p></div></div><div class="pf-stats"><span>2,456 Cards</span><span>305 Families</span><span>320 Packs opened</span></div></header><section class="sec pf-albums" aria-labelledby="h-featured"><div class="sec-head"><h2 id="h-featured">Albums</h2></div><div class="tiles"><article class="tile"><div></div>Favourite cards</article><article class="tile"><div></div>Around the world</article><article class="tile"><div></div>Science</article></div></section><section class="sec" aria-labelledby="h-showcase"><div class="sec-head"><h2 id="h-showcase">Showcase</h2></div><div class="tile">Featured cards</div></section></div></main></body></html>`;
}
